-- CloudPulse AI 3NF Relational Database Dump
-- Architecture: SQLite 3
-- Standard: UTC Timestamps & Active Presentation Reporting Views
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

CREATE TABLE addons (
    addon_id INTEGER PRIMARY KEY,
    addon_name VARCHAR(100) NOT NULL UNIQUE,
    monthly_price DECIMAL(10, 2) NOT NULL
);
CREATE TABLE customers (
    customer_id VARCHAR(20) PRIMARY KEY,
    customer_name VARCHAR(150) NOT NULL,
    customer_email VARCHAR(255) NOT NULL,
    customer_company VARCHAR(150) NOT NULL,
    customer_country VARCHAR(100) NOT NULL,
    signup_timestamp DATETIME NOT NULL,
    is_sandbox INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE invoices (
    invoice_id VARCHAR(30) PRIMARY KEY,
    customer_id VARCHAR(20) NOT NULL,
    subscription_id INTEGER,
    invoice_timestamp DATETIME NOT NULL,
    plan_code VARCHAR(50) NOT NULL,
    amount_billed DECIMAL(10, 2) NOT NULL,
    payment_status VARCHAR(20) NOT NULL,
    payment_method VARCHAR(50) NOT NULL,
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (subscription_id) REFERENCES subscriptions(subscription_id),
    FOREIGN KEY (plan_code) REFERENCES plans(plan_code)
);
CREATE TABLE plans (
    plan_code VARCHAR(50) PRIMARY KEY,
    plan_name VARCHAR(100) NOT NULL,
    billing_interval VARCHAR(20) NOT NULL,
    base_price DECIMAL(10, 2) NOT NULL
);
CREATE TABLE refunds (
    refund_id VARCHAR(30) PRIMARY KEY,
    customer_id VARCHAR(20) NOT NULL,
    subscription_id INTEGER,
    refund_timestamp DATETIME NOT NULL,
    refund_amount DECIMAL(10, 2) NOT NULL,
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (subscription_id) REFERENCES subscriptions(subscription_id)
);
CREATE TABLE subscription_addons (
    subscription_id INTEGER NOT NULL,
    addon_id INTEGER NOT NULL,
    PRIMARY KEY (subscription_id, addon_id),
    FOREIGN KEY (subscription_id) REFERENCES subscriptions(subscription_id),
    FOREIGN KEY (addon_id) REFERENCES addons(addon_id)
);
CREATE TABLE subscription_events (
    event_id VARCHAR(30) PRIMARY KEY,
    event_timestamp DATETIME NOT NULL,
    event_type VARCHAR(50) NOT NULL,
    customer_id VARCHAR(20) NOT NULL,
    plan_code VARCHAR(50) NOT NULL,
    billing_interval VARCHAR(20) NOT NULL,
    amount_billed DECIMAL(10, 2) NOT NULL,
    payment_status VARCHAR(20) NOT NULL,
    payment_method VARCHAR(50) NOT NULL,
    refund_amount DECIMAL(10, 2) NOT NULL,
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);
CREATE TABLE subscriptions (
    subscription_id INTEGER PRIMARY KEY AUTOINCREMENT,
    customer_id VARCHAR(20) NOT NULL,
    plan_code VARCHAR(50) NOT NULL,
    billing_interval VARCHAR(20) NOT NULL,
    subscription_status VARCHAR(30) NOT NULL,
    created_at DATETIME NOT NULL,
    canceled_at DATETIME,
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (plan_code) REFERENCES plans(plan_code)
);
CREATE VIEW v_invoices_reporting AS
SELECT 
    invoice_id,
    customer_id,
    subscription_id,
    invoice_timestamp,
    plan_code,
    ROUND(amount_billed, 2) AS amount_billed,
    payment_status,
    payment_method
FROM invoices;
CREATE VIEW v_refunds_reporting AS
SELECT 
    refund_id,
    customer_id,
    subscription_id,
    refund_timestamp,
    ROUND(refund_amount, 2) AS refund_amount
FROM refunds;
CREATE VIEW v_annual_revenue AS
SELECT 
    strftime('%Y', invoice_timestamp) AS year,
    COUNT(invoice_id) AS total_invoices,
    SUM(CASE WHEN payment_status = 'paid' THEN 1 ELSE 0 END) AS paid_invoices,
    ROUND(SUM(CASE WHEN payment_status = 'paid' THEN amount_billed ELSE 0 END), 2) AS gross_paid_revenue,
    ROUND(SUM(CASE WHEN payment_status = 'failed' THEN amount_billed ELSE 0 END), 2) AS failed_invoiced_amount,
    COALESCE(r.total_refunds, 0.0) AS refunds_issued,
    ROUND(SUM(CASE WHEN payment_status = 'paid' THEN amount_billed ELSE 0 END) - COALESCE(r.total_refunds, 0.0), 2) AS net_realized_revenue
FROM invoices i
LEFT JOIN (
    SELECT strftime('%Y', refund_timestamp) AS ref_year, ROUND(SUM(refund_amount), 2) AS total_refunds
    FROM refunds
    GROUP BY ref_year
) r ON strftime('%Y', i.invoice_timestamp) = r.ref_year
GROUP BY year
ORDER BY year;
CREATE INDEX idx_customers_email ON customers(customer_email);
CREATE INDEX idx_subs_customer ON subscriptions(customer_id);
CREATE INDEX idx_invoices_date ON invoices(invoice_timestamp);
CREATE INDEX idx_invoices_customer ON invoices(customer_id);
CREATE INDEX idx_events_customer ON subscription_events(customer_id);
DELETE FROM "sqlite_sequence";

COMMIT;
PRAGMA foreign_keys = ON;
